/**
 * Cookie-consent state, shared between the banner and the two floating widgets
 * it used to sit on top of.
 *
 * The banner (`components/marketing/CookieConsent.tsx`), the chat bubble
 * (`components/ChatWidget.tsx`) and the feedback button
 * (`components/FeedbackWidget.tsx`) all occupy the bottom of the viewport. On a
 * first visit the banner is the only one of the three the visitor must act on,
 * so it wins the stacking order — and the other two get out of its way until a
 * choice exists. That needs one definition of "has a choice been made", plus a
 * way for the widgets to hear about the choice the moment it is made rather than
 * on the next page load.
 *
 * Browser-only module: no imports, safe in any client component.
 */

export const CONSENT_COOKIE = "nxeon_cookie_consent";
export const CONSENT_MAX_AGE = 60 * 60 * 24 * 365;

/** Fired on `window` when a visitor accepts or declines, so widgets re-measure. */
export const CONSENT_EVENT = "nxeon:cookie-consent";

/** True once the visitor has chosen. SSR-safe: assumes chosen, so nothing moves. */
export function hasCookieConsent(): boolean {
  if (typeof document === "undefined") return true;
  try {
    return document.cookie.split("; ").some((c) => c.startsWith(`${CONSENT_COOKIE}=`));
  } catch {
    // Cookies blocked entirely — treat as decided so we never pin a banner-shaped
    // hole in the corner of a page whose banner will never appear.
    return true;
  }
}

export function setCookieConsent(value: "all" | "necessary") {
  document.cookie = `${CONSENT_COOKIE}=${value}; path=/; max-age=${CONSENT_MAX_AGE}; SameSite=Lax`;
}

/**
 * The visitor's actual choice: "all" (accepted analytics + marketing cookies),
 * "necessary" (rejected them), or null (no choice yet). Marketing/advertising tags
 * (Meta Pixel, Google Ads/GA4) may load ONLY on "all". SSR-safe: returns null on
 * the server so the gate renders nothing until the client re-measures.
 */
export function getCookieConsent(): "all" | "necessary" | null {
  if (typeof document === "undefined") return null;
  try {
    const hit = document.cookie
      .split("; ")
      .find((c) => c.startsWith(`${CONSENT_COOKIE}=`));
    if (!hit) return null;
    const val = hit.slice(CONSENT_COOKIE.length + 1);
    return val === "all" ? "all" : "necessary";
  } catch {
    return null;
  }
}

/**
 * Whether marketing/advertising tags (Meta Pixel, Google Ads/GA4) may load.
 *
 * DEFAULT-ON / opt-out model (owner decision to maximise ad-pixel event volume
 * in non-EU markets): tracking is allowed unless the visitor has EXPLICITLY
 * opted out by choosing "necessary". Both the absence of a choice (null) and an
 * explicit "all" allow it; only "necessary" blocks it.
 *
 * SSR-safe: on the server `getCookieConsent()` returns null, so this returns
 * true — but the tag gate still only renders after it mounts on the client, so
 * no marketing script is emitted during SSR regardless.
 */
export function marketingAllowed(): boolean {
  return getCookieConsent() !== "necessary";
}

// Ads conversion tracking — Meta Pixel + Google Ads/GA4, browser + server-side.
//
// IDs live in Settings (admin-editable, no redeploy). The browser side is injected
// by components/marketing/ConversionTags.tsx; the SERVER side is the Meta
// Conversions API (CAPI) below, which recovers the conversions iOS/ad-blockers hide
// from the pixel. Everything is inert until the IDs/token are set — no config,
// nothing fires, nothing leaks.
import { createHash, randomUUID } from "node:crypto";
import { getSetting } from "@/lib/settings";
import { decryptSecret } from "@/lib/crypto-box";

/**
 * Per-funnel Google Ads conversion labels. Each maps a funnel event to the label an
 * operator pastes from Google Ads; an empty label keeps that conversion INERT (the
 * paired Meta standard event still fires). `purchase` mirrors `googleAdsPurchaseLabel`
 * so every conversion — including the existing paid-order Purchase — is addressed the
 * same way.
 */
export type GoogleAdsLabels = {
  signup: string;
  vps: string;
  hosting: string;
  game: string;
  email: string;
  card: string;
  purchase: string;
};

export type TrackingConfig = {
  metaPixelId: string;
  ga4Id: string;
  googleAdsId: string; // AW-XXXXXXXXX
  googleAdsPurchaseLabel: string; // conversion label for a purchase
  /** Per-funnel Google Ads conversion labels (see GoogleAdsLabels). */
  googleAdsLabels: GoogleAdsLabels;
  // Server-only (never sent to the browser):
  metaCapiToken: string;
  metaTestEventCode: string;
};

/** Public (browser-safe) subset — safe to serialize into the page. */
export type PublicTrackingConfig = Pick<
  TrackingConfig,
  "metaPixelId" | "ga4Id" | "googleAdsId" | "googleAdsPurchaseLabel" | "googleAdsLabels"
>;

export async function loadTrackingConfig(): Promise<TrackingConfig> {
  const [
    metaPixelId,
    ga4Id,
    googleAdsId,
    googleAdsPurchaseLabel,
    signupLabel,
    vpsLabel,
    hostingLabel,
    gameLabel,
    emailLabel,
    cardLabel,
    metaCapiToken,
    metaTestEventCode,
  ] = await Promise.all([
    getSetting("meta_pixel_id", ""),
    getSetting("ga4_measurement_id", ""),
    getSetting("google_ads_id", ""),
    getSetting("google_ads_purchase_label", ""),
    getSetting("google_ads_signup_label", ""),
    getSetting("google_ads_vps_label", ""),
    getSetting("google_ads_hosting_label", ""),
    getSetting("google_ads_game_label", ""),
    getSetting("google_ads_email_label", ""),
    getSetting("google_ads_card_label", ""),
    getSetting("meta_capi_token", ""),
    getSetting("meta_test_event_code", ""),
  ]);
  // The CAPI token is stored encrypted (a `secret` field); decrypt for use.
  const decToken = metaCapiToken ? (decryptSecret(metaCapiToken) ?? metaCapiToken) : "";
  const purchaseLabel = googleAdsPurchaseLabel.trim();
  return {
    metaPixelId: metaPixelId.trim(),
    ga4Id: ga4Id.trim(),
    googleAdsId: googleAdsId.trim(),
    googleAdsPurchaseLabel: purchaseLabel,
    googleAdsLabels: {
      signup: signupLabel.trim(),
      vps: vpsLabel.trim(),
      hosting: hostingLabel.trim(),
      game: gameLabel.trim(),
      email: emailLabel.trim(),
      card: cardLabel.trim(),
      purchase: purchaseLabel,
    },
    metaCapiToken: decToken.trim(),
    metaTestEventCode: metaTestEventCode.trim(),
  };
}

export function toPublicConfig(c: TrackingConfig): PublicTrackingConfig {
  return {
    metaPixelId: c.metaPixelId,
    ga4Id: c.ga4Id,
    googleAdsId: c.googleAdsId,
    googleAdsPurchaseLabel: c.googleAdsPurchaseLabel,
    googleAdsLabels: c.googleAdsLabels,
  };
}

function sha256Lower(s: string): string {
  return createHash("sha256").update(s.trim().toLowerCase()).digest("hex");
}

export type CapiEvent = {
  eventName: "Purchase" | "Lead" | "CompleteRegistration" | "Subscribe";
  /** Stable id so the browser pixel + this server event dedupe to ONE conversion. */
  eventId?: string;
  email?: string;
  value?: number;
  currency?: string;
  /** The page the conversion happened on (for event_source_url). */
  sourceUrl?: string;
  clientIp?: string;
  userAgent?: string;
  /** Meta click-id cookie (_fbc) — sent RAW (not hashed) per Meta spec. */
  fbc?: string;
  /** Meta browser-id cookie (_fbp) — sent RAW (not hashed) per Meta spec. */
  fbp?: string;
  /** A stable id for the person (we use the user id, hashed) — big match boost. */
  externalId?: string;
};

/**
 * Fire a server-side Meta Conversions API event. Best-effort: never throws into
 * the caller (a tracking failure must never break an order). Returns the event_id
 * used so the caller can pass the SAME id to the browser pixel for dedup.
 */
export async function sendMetaConversion(ev: CapiEvent): Promise<{ ok: boolean; eventId: string }> {
  const eventId = ev.eventId ?? randomUUID();
  try {
    const cfg = await loadTrackingConfig();
    if (!cfg.metaPixelId || !cfg.metaCapiToken) return { ok: false, eventId };

    const userData: Record<string, unknown> = {};
    if (ev.email) userData.em = [sha256Lower(ev.email)];
    if (ev.clientIp) userData.client_ip_address = ev.clientIp;
    if (ev.userAgent) userData.client_user_agent = ev.userAgent;
    // fbc/fbp are sent RAW (Meta hashes nothing here); external_id IS hashed. All
    // three materially lift the event match rate when present.
    if (ev.fbc) userData.fbc = ev.fbc;
    if (ev.fbp) userData.fbp = ev.fbp;
    if (ev.externalId) userData.external_id = [sha256Lower(ev.externalId)];

    const body: Record<string, unknown> = {
      data: [
        {
          event_name: ev.eventName,
          event_time: Math.floor(Date.now() / 1000),
          action_source: "website",
          event_id: eventId,
          ...(ev.sourceUrl ? { event_source_url: ev.sourceUrl } : {}),
          user_data: userData,
          ...(ev.value != null
            ? { custom_data: { value: Number(ev.value.toFixed(2)), currency: ev.currency ?? "USD" } }
            : {}),
        },
      ],
      ...(cfg.metaTestEventCode ? { test_event_code: cfg.metaTestEventCode } : {}),
    };

    const url = `https://graph.facebook.com/v21.0/${encodeURIComponent(cfg.metaPixelId)}/events?access_token=${encodeURIComponent(cfg.metaCapiToken)}`;
    const res = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
      // Don't let a slow Meta endpoint hang a checkout.
      signal: AbortSignal.timeout(4000),
    });
    return { ok: res.ok, eventId };
  } catch {
    return { ok: false, eventId };
  }
}

"use client";

import Script from "next/script";
import type { PublicTrackingConfig } from "@/lib/tracking";

/**
 * Browser-side ad tags: Meta Pixel + Google Ads/GA4 gtag. Handed the PUBLIC config
 * (no CAPI token) read from Settings, and renders nothing unless an ID is set. Also
 * installs `window.nxTrack(event, params)` so any client component can fire a
 * conversion (e.g. a Purchase on the order-success view) to BOTH Meta and Google in
 * one call, using a shared event_id for dedup with CAPI.
 *
 * Consent gating lives in its wrapper `ConsentedTags.tsx` — these scripts are only
 * ever mounted once the visitor has accepted all cookies, so the marketing/advertising
 * pixels never load without consent.
 */
export function ConversionTags({ config }: { config: PublicTrackingConfig }) {
  const { metaPixelId, ga4Id, googleAdsId, googleAdsPurchaseLabel, googleAdsLabels } = config;
  if (!metaPixelId && !ga4Id && !googleAdsId) return null;

  const gtagId = ga4Id || googleAdsId; // one gtag.js load covers both

  // Action key → { Meta standard event, Google Ads conversion label }. Built here
  // (server-side) and serialized into the script as JSON so labels can never break
  // out of the string. An empty `g` keeps that Google conversion INERT; the Meta
  // event (`m`) always fires. `purchase` carries the existing purchase label so the
  // paid-order conversion routes through the same map.
  const labels = googleAdsLabels ?? {
    signup: "", vps: "", hosting: "", game: "", email: "", card: "", purchase: googleAdsPurchaseLabel,
  };
  const actionMap: Record<string, { m: string; g: string }> = {
    signup: { m: "CompleteRegistration", g: labels.signup || "" },
    // vps/game are GOOGLE-ONLY (m:"") — the paid order already fires ONE Meta
    // Purchase via the 'purchase' key at fulfilment (deduped by event id). Firing a
    // second Meta Purchase here would double-count. They fire at fulfilment (see
    // PurchaseTracker) with the REAL charged value + transaction_id, not at
    // checkout-start (which would count Stripe abandoners).
    vps: { m: "", g: labels.vps || "" },
    hosting: { m: "Subscribe", g: labels.hosting || "" },
    game: { m: "", g: labels.game || "" },
    email: { m: "Subscribe", g: labels.email || "" },
    card: { m: "AddPaymentInfo", g: labels.card || "" },
    purchase: { m: "Purchase", g: labels.purchase || googleAdsPurchaseLabel || "" },
  };
  return (
    <>
      {metaPixelId && (
        <Script id="meta-pixel" strategy="afterInteractive">
          {`!function(f,b,e,v,n,t,s){if(f.fbq)return;n=f.fbq=function(){n.callMethod?
n.callMethod.apply(n,arguments):n.queue.push(arguments)};if(!f._fbq)f._fbq=n;
n.push=n;n.loaded=!0;n.version='2.0';n.queue=[];t=b.createElement(e);t.async=!0;
t.src=v;s=b.getElementsByTagName(e)[0];s.parentNode.insertBefore(t,s)}(window,
document,'script','https://connect.facebook.net/en_US/fbevents.js');
fbq('init','${metaPixelId}');fbq('track','PageView');`}
        </Script>
      )}
      {gtagId && (
        <>
          <Script src={`https://www.googletagmanager.com/gtag/js?id=${gtagId}`} strategy="afterInteractive" />
          <Script id="gtag-init" strategy="afterInteractive">
            {`window.dataLayer=window.dataLayer||[];function gtag(){dataLayer.push(arguments);}
gtag('js',new Date());${ga4Id ? `gtag('config','${ga4Id}');` : ""}${googleAdsId ? `gtag('config','${googleAdsId}');` : ""}`}
          </Script>
        </>
      )}
      {/*
        Unified conversion helper. Usage: window.nxTrack('vps',{value:3.29,currency:'USD',eventId}).
        `key` is a FUNNEL ACTION KEY (signup/vps/hosting/game/email/card/purchase) mapped
        below to a Meta standard event + a Google Ads label. An UNKNOWN key falls back to
        the old behaviour — treated as a raw Meta event name, with Google fired only for
        'Purchase' using the purchase label — so any legacy caller keeps working.
      */}
      <Script id="nx-track" strategy="afterInteractive">
        {`window.nxTrack=function(key,p){p=p||{};try{
var M=${JSON.stringify(actionMap)};
var GA4=${JSON.stringify(ga4Id)};
var ADS=${JSON.stringify(googleAdsId)};
var PLBL=${JSON.stringify(googleAdsPurchaseLabel)};
var e=M[key];
var mEvt=e?e.m:key;
if(mEvt&&window.fbq){fbq('track',mEvt,{value:p.value,currency:p.currency||'USD'},p.eventId?{eventID:p.eventId}:undefined);}
if(window.gtag){
  if(GA4)gtag('event',String(key).toLowerCase(),{value:p.value,currency:p.currency||'USD'});
  if(ADS){
    if(e){if(e.g)gtag('event','conversion',{send_to:ADS+'/'+e.g,value:p.value,currency:p.currency||'USD',transaction_id:p.eventId||''});}
    else if(key==='Purchase'&&PLBL){gtag('event','conversion',{send_to:ADS+'/'+PLBL,value:p.value,currency:p.currency||'USD',transaction_id:p.eventId||''});}
  }
}
}catch(e){}};`}
      </Script>
    </>
  );
}

===== ConsentedTags.tsx =====
"use client";

import { useEffect, useState } from "react";
import { CONSENT_EVENT, marketingAllowed } from "@/lib/consent";
import type { PublicTrackingConfig } from "@/lib/tracking";
import { ConversionTags } from "./ConversionTags";

/**
 * Consent gate for the ad-tracking pixels (Meta Pixel + Google Ads/GA4).
 *
 * DEFAULT-ON / opt-out model: tracking is allowed by default and only suppressed
 * when the visitor has EXPLICITLY opted out ("necessary") in the cookie notice
 * (`CookieConsent.tsx`). See `marketingAllowed()` in `lib/consent.ts`.
 *
 * SSR renders nothing (we start `allowed=false` and only flip it on after the
 * client mounts), so no marketing script is emitted during SSR. Once mounted we
 * read the choice and re-measure on the `CONSENT_EVENT` the notice dispatches, so
 * the tags come to life — or go away — the instant a visitor makes a choice, no
 * page reload required. If the operator has set no ids, `ConversionTags` itself
 * still renders nothing, so this stays doubly inert until BOTH an id exists AND
 * the visitor has not opted out.
 */
export function ConsentedTags({ config }: { config: PublicTrackingConfig }) {
  const [allowed, setAllowed] = useState(false);

  useEffect(() => {
    const sync = () => setAllowed(marketingAllowed());
    sync();
    window.addEventListener(CONSENT_EVENT, sync);
    return () => window.removeEventListener(CONSENT_EVENT, sync);
  }, []);

  if (!allowed) return null;
  return <ConversionTags config={config} />;
}
===== SignupTracker.tsx =====
"use client";

import { useEffect } from "react";

/**
 * Fires the browser-side "signup" conversion when a freshly registered account
 * lands on the dashboard.
 *
 * `register()` (lib/actions.ts) redirects a completed signup to
 * `/dashboard?signup=1`. Registration is a server action that finishes with a
 * server-side `redirect`, so there is no client success handler on the form itself
 * — this marker is how the completion becomes observable to the pixel. We strip the
 * marker immediately (history.replaceState) so a refresh or back-navigation can
 * never double-count, then hand off to `window.nxTrack('signup')` (installed by
 * ConversionTags). `nxTrack` only exists once the pixel has loaded, which only
 * happens after cookie consent — so with no ids or no consent this is a silent
 * no-op. Best-effort and non-blocking, exactly like PurchaseTracker.
 */
export function SignupTracker() {
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    if (params.get("signup") !== "1") return;

    // Strip the marker before doing anything else so a reload/back cannot re-fire.
    params.delete("signup");
    const qs = params.toString();
    window.history.replaceState(
      null,
      "",
      window.location.pathname + (qs ? `?${qs}` : "") + window.location.hash,
    );

    // The pixel loads afterInteractive and only once consent is granted — retry a
    // few seconds for nxTrack to appear, then give up.
    let tries = 0;
    let timer: ReturnType<typeof setTimeout> | undefined;
    const fire = () => {
      const nx = (window as unknown as { nxTrack?: (k: string, p?: Record<string, unknown>) => void }).nxTrack;
      if (typeof nx === "function") {
        try {
          nx("signup", {});
        } catch {
          /* best-effort */
        }
        return;
      }
      if (tries++ < 40) timer = setTimeout(fire, 250);
    };
    fire();
    return () => {
      if (timer) clearTimeout(timer);
    };
  }, []);

  return null;
}
===== PurchaseTracker.tsx =====
"use client";

import { useEffect } from "react";

/**
 * Fires the browser-side Purchase conversion when a paid order lands here.
 *
 * `lib/fulfil-checkout.ts` tags the post-checkout redirect with the real charged
 * amount when (and only when) IT performed the fulfilment — `?purchase=1&pv=<value>
 * &pc=<currency>&pe=<eventId>`. That same call already fired the server-side Meta
 * Conversions API event with the SAME `eventId`, so when the pixel fires here Meta
 * dedupes the two into ONE conversion.
 *
 * We strip the markers from the URL immediately (history.replaceState) so a refresh
 * or back-navigation can never double-count, then hand the value to `window.nxTrack`
 * (installed by ConversionTags). `nxTrack` only exists once the pixel has loaded,
 * which only happens after cookie consent — so with no ids or no consent this is a
 * silent no-op, and the CAPI event already covered the conversion server-side.
 */
export function PurchaseTracker() {
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    if (params.get("purchase") !== "1") return;

    const value = Number(params.get("pv") ?? "0");
    const currency = params.get("pc") ?? "USD";
    const eventId = params.get("pe") ?? undefined;
    // Product kind (vps|game) → also fire that per-funnel conversion at FULFILMENT
    // with the REAL charged value + the same transaction_id. Those keys are
    // Google-ONLY (Meta already got its single Purchase from the 'purchase' key).
    const prod = params.get("prod") || "";

    // Strip the markers before doing anything else so a reload/back cannot re-fire.
    for (const k of ["purchase", "pv", "pc", "pe", "prod"]) params.delete(k);
    const qs = params.toString();
    window.history.replaceState(
      null,
      "",
      window.location.pathname + (qs ? `?${qs}` : "") + window.location.hash,
    );

    if (!(value > 0)) return;

    // The pixel loads afterInteractive and only once consent is granted — retry a
    // few seconds for nxTrack to appear, then give up (CAPI already covered it).
    let tries = 0;
    let timer: ReturnType<typeof setTimeout> | undefined;
    const fire = () => {
      const nx = (window as unknown as { nxTrack?: (e: string, p: unknown) => void }).nxTrack;
      if (typeof nx === "function") {
        // 'purchase' is the mapped action key (→ Meta Purchase + the Google Ads
        // purchase label); nxTrack still accepts the legacy 'Purchase' too.
        nx("purchase", { value, currency, eventId });
        // Product-specific Google Ads conversion (vps|game) with the REAL charged
        // value + same transaction_id. Google-only (Meta got its Purchase above).
        if (prod === "vps" || prod === "game") nx(prod, { value, currency, eventId });
        return;
      }
      if (tries++ < 40) timer = setTimeout(fire, 250);
    };
    fire();
    return () => {
      if (timer) clearTimeout(timer);
    };
  }, []);

  return null;
}

