"use client";

import { useEffect, useRef } from "react";
import { usePathname } from "next/navigation";
import { marketingAllowed } from "@/lib/consent";

/**
 * Two Meta-pixel gaps the base code in `ConversionTags.tsx` can't cover on its own,
 * both live site-wide from the root layout. No-op with no pixel or an opted-out
 * visitor (`marketingAllowed()` is the same DEFAULT-ON/opt-out gate the tags use).
 *
 * 1. SPA PageView. The base pixel fires `fbq('track','PageView')` ONCE, when the
 *    script first loads. App Router navigation swaps content without a document
 *    reload, so a visitor who browses five pages otherwise books ONE PageView (or
 *    zero, if the pixel loaded after they'd already moved). This re-fires PageView
 *    on every client-side route change — the single biggest cause of the pixel
 *    undercounting real traffic. The first mount is skipped: the base code already
 *    counted the landing page, and firing here too would double it.
 *
 * 2. fbc coverage. Meta only sets the `_fbc` click cookie when the pixel loads with
 *    an `fbclid` in the URL — so an ad click into an ad-blocking/iOS browser leaves
 *    NO `_fbc`, and every server CAPI event for that visitor ships without the
 *    strongest match signal Meta warns us about ("low coverage of fbc"). We mirror
 *    the pixel and write the cookie ourselves, first-party, in Meta's exact
 *    `fb.1.<timestamp>.<fbclid>` format, so every later CAPI call (signup, order,
 *    hosting) can read it even when the pixel never ran. Only written when absent so
 *    we never clobber the pixel's own value.
 */
export default function MetaPixelTracker() {
  const pathname = usePathname();
  const first = useRef(true);

  useEffect(() => {
    if (typeof window === "undefined") return;
    // Honour the opt-out: _fbc is a marketing cookie and PageView is a marketing tag.
    if (!marketingAllowed()) return;

    // Capture fbclid → first-party _fbc cookie (survives ad-blockers that kill the pixel).
    try {
      const fbclid = new URLSearchParams(window.location.search).get("fbclid");
      const hasFbc = document.cookie.split("; ").some((c) => c.startsWith("_fbc="));
      if (fbclid && !hasFbc) {
        document.cookie = `_fbc=fb.1.${Date.now()}.${fbclid}; path=/; max-age=${60 * 60 * 24 * 90}; SameSite=Lax`;
      }
    } catch {
      /* cookies blocked — nothing to capture */
    }

    // Skip the initial mount (base pixel already counted this page); re-fire on nav.
    if (first.current) {
      first.current = false;
      return;
    }
    const fbq = (window as unknown as { fbq?: (...args: unknown[]) => void }).fbq;
    if (typeof fbq === "function") fbq("track", "PageView");
  }, [pathname]);

  return null;
}

